  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA", 50);
  brush.fillBleed(0.3);
  brush.fillTexture(1, 0);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#1e90ff", 70);
  brush.fillBleed(0.5);
  brush.fillTexture(0.8, 0);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#ffcc00", 100);
  brush.fillBleed(0.7);
  brush.fillTexture(0.9, 0);
  brush.beginShape();
  brush.vertex(0, 100);
  brush.vertex(400, 100);
  brush.vertex(400, 50);
  brush.vertex(0, 50);
  brush.endShape(true);

  // Clouds
  brush.fill("#e0e0e0", 60);
  brush.fillBleed(0.4);
  brush.fillTexture(0.6, 0);
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(400, 350);
  brush.vertex(0, 350);
  brush.endShape(true);
}
