  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEFA"); // Blue sky
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#90EE90"); // Green hills
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Yellow sun
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(220, 80);
  brush.vertex(230, 100);
  brush.vertex(210, 120);
  brush.endShape(true);
}
